import java.util.Optional;

public interface AuthService {
    UserResponse register(RegisterRequest request);
    LoginResponse login(LoginRequest request);
    TokenResponse refreshTokens(String refreshToken);
    
    /**
     * ユーザーをログアウトし、リフレッシュトークンを無効化する
     * @param username ログアウト対象のユーザー名
     * @param refreshToken 無効化するリフレッシュトークン（オプショナル）
     */
    void logout(String username, Optional<String>

@Override
@Transactional
public void logout(String username, Optional<String> refreshTokenValue) {
    // リフレッシュトークンが指定されている場合、DB 上で無効化する
    if (refreshTokenValue.isPresent() && !refreshTokenValue.get().isEmpty()) {
        String tokenHash = TokenUtil.hashToken(refreshTokenValue.get(), tokenSecret);
        Optional<RefreshToken> optToken = refreshTokenRepository.findByTokenHash(tokenHash);
        
        if (optToken.isPresent()) {
            RefreshToken refreshToken = optToken.get();
            
            // トークンがリクエストしたユーザーに属しているか確認
            if (!refreshToken.getUser().getUsername().equals(username)) {
                throw new InvalidTokenException("Token does not belong to the user");
            }
            
            // まだ無効化されていない場合のみ処理
            if (!refreshToken.isRevoked()) {
                refreshToken.setRevoked(true);
                refreshToken.setRevokedAt(Instant.now());
                refreshTokenRepository.save(refreshToken);
            }
        }
        // トークンが存在しない場合は静かに成功扱い（冪等性確保）
    }
    
    // 将来の拡張: Redis ブラックリストへアクセストークン jti を追加する処理をここに実装可能
}

/**
 * ログアウトエンドポイント
 * リフレッシュトークンを無効化し、ユーザーをログアウトする
 * 
 * 注意: 現在の実装では簡易的にユーザー名をリクエストパラメータから取得しています。
 * 本番環境では、アクセストークンを検証して SecurityContext からユーザー情報を取得することを推奨します。
 */
@PostMapping("/logout")
public ResponseEntity<?> logout(
        @RequestBody(required = false) LogoutRequest request,
        @RequestParam(value = "username", required = true) String username) {
    
    String refreshToken = (request != null) ? request.getRefreshToken() : null;
    authService.logout(username, Optional.ofNullable(refreshToken));
    
    return ResponseEntity.ok(Map.of("message", "Logged out successfully"));
}

    // ========== ログアウト関連のテスト ==========

    @Test
    void logout_withValidRefreshToken_revokesToken() {
        // 有効なリフレッシュトークンを指定してログアウトすると、該当トークンが無効化されることを検証する
        // Arrange
        String refreshTokenValue = "valid-refresh-token";
        User user = new User();
        user.setId(1L);
        user.setUsername("testuser");

        RefreshToken refreshToken = new RefreshToken();
        refreshToken.setId(1L);
        refreshToken.setUser(user);
        refreshToken.setRevoked(false);
        refreshToken.setExpiresAt(Instant.now().plusSeconds(3600));

        when(refreshTokenRepository.findByTokenHash(anyString())).thenReturn(Optional.of(refreshToken));
        when(refreshTokenRepository.save(any(RefreshToken.class))).thenAnswer(inv -> inv.getArgument(0));

        // Act
        authService.logout("testuser", Optional.of(refreshTokenValue));

        // Assert
        assertTrue(refreshToken.isRevoked(), "Refresh token should be revoked");
        assertNotNull(refreshToken.getRevokedAt(), "Revoked timestamp should be set");
        verify(refreshTokenRepository, times(1)).save(refreshToken);
    }

    @Test
    void logout_withoutRefreshToken_succeedsQuietly() {
        // リフレッシュトークンなしでログアウトしても、エラーなく成功すること（冪等性）を検証する
        // Act & Assert - no exception should be thrown
        assertDoesNotThrow(() -> authService.logout("testuser", Optional.empty()));
        
        // Verify no token repository interactions
        verify(refreshTokenRepository, never()).findByTokenHash(anyString());
        verify(refreshTokenRepository, never()).save(any(RefreshToken.class));
    }

    @Test
    void logout_withEmptyRefreshToken_succeedsQuietly() {
        // 空のリフレッシュトークン文字列でログアウトしても、エラーなく成功すること（冪等性）を検証する
        // Act & Assert - no exception should be thrown
        assertDoesNotThrow(() -> authService.logout("testuser", Optional.of("")));
        
        // Verify no token repository interactions
        verify(refreshTokenRepository, never()).findByTokenHash(anyString());
        verify(refreshTokenRepository, never()).save(any(RefreshToken.class));
    }

    @Test
    void logout_withNonExistentToken_succeedsQuietly() {
        // 存在しないトークンでログアウトしても、エラーなく成功すること（冪等性）を検証する
        // Arrange
        when(refreshTokenRepository.findByTokenHash(anyString())).thenReturn(Optional.empty());

        // Act & Assert - no exception should be thrown
        assertDoesNotThrow(() -> authService.logout("testuser", Optional.of("non-existent-token")));
        verify(refreshTokenRepository, never()).save(any(RefreshToken.class));
    }

    @Test
    void logout_withAlreadyRevokedToken_succeedsQuietly() {
        // 既に無効化されたトークンでログアウトしても、エラーなく成功すること（冪等性）を検証する
        // Arrange
        String refreshTokenValue = "already-revoked-token";
        User user = new User();
        user.setId(1L);
        user.setUsername("testuser");

        RefreshToken refreshToken = new RefreshToken();
        refreshToken.setId(1L);
        refreshToken.setUser(user);
        refreshToken.setRevoked(true);
        refreshToken.setRevokedAt(Instant.now().minusSeconds(3600));

        when(refreshTokenRepository.findByTokenHash(anyString())).thenReturn(Optional.of(refreshToken));

        // Act & Assert - no exception should be thrown
        assertDoesNotThrow(() -> authService.logout("testuser", Optional.of(refreshTokenValue)));
        
        // Verify no save was called since token was already revoked
        verify(refreshTokenRepository, never()).save(any(RefreshToken.class));
    }

    @Test
    void logout_withTokenBelongingToOtherUser_throwsException() {
        // 他のユーザーのトークンでログアウトを試みた場合、InvalidTokenException が投げられることを検証する
        // Arrange
        String refreshTokenValue = "other-users-token";
        User otherUser = new User();
        otherUser.setId(2L);
        otherUser.setUsername("otheruser");

        RefreshToken refreshToken = new RefreshToken();
        refreshToken.setId(1L);
        refreshToken.setUser(otherUser);
        refreshToken.setRevoked(false);
        refreshToken.setExpiresAt(Instant.now().plusSeconds(3600));

        when(refreshTokenRepository.findByTokenHash(anyString())).thenReturn(Optional.of(refreshToken));

        // Act & Assert
        assertThrows(InvalidTokenException.class, 
            () -> authService.logout("testuser", Optional.of(refreshTokenValue)),
            "Should throw InvalidTokenException when token belongs to another user");
        
        // Verify token was not revoked
        verify(refreshTokenRepository, never()).save(any(RefreshToken.class));
    }

